package clusterdata.datatypes;

import java.io.Serializable;

public class JobEvent implements Serializable {
    public long timestamp;
    public String missingInfo;
    public long jobId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public String jobName;
    public String logicalJobName;

    public JobEvent() {}

    public JobEvent(long timestamp, String missingInfo, long jobId, int eventType, String userName, int schedulingClass, String jobName, String logicalJobName) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.jobName = jobName;
        this.logicalJobName = logicalJobName;
    }

    public static JobEvent fromString(String line) {
        String[] tokens = line.split(",");
        if (tokens.length < 8) return null;

        try {
            long timestamp = Long.parseLong(tokens[0]);
            String missingInfo = tokens[1];
            long jobId = Long.parseLong(tokens[2]);
            int eventType = Integer.parseInt(tokens[3]);
            String userName = tokens[4];
            int schedulingClass = tokens[5].isEmpty() ? -1 : Integer.parseInt(tokens[5]);
            String jobName = tokens[6];
            String logicalJobName = tokens[7];

            return new JobEvent(timestamp, missingInfo, jobId, eventType, userName, schedulingClass, jobName, logicalJobName);
        } catch (NumberFormatException e) {
            // Log or handle error
            return null;
        }
    }

    @Override
    public String toString() {
        return "JobEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", eventType=" + eventType +
                '}';
    }
}

package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    public long timestamp;
    public String missingInfo;
    public long jobId;
    public int taskIndex;
    public String machineId; // Keeping as String as it might be empty or hash
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public float cpuRequest;
    public float ramRequest;
    public float diskRequest;
    public boolean differentMachineConstraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, int taskIndex, String machineId, int eventType,
                     String userName, int schedulingClass, int priority, float cpuRequest, float ramRequest,
                     float diskRequest, boolean differentMachineConstraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.ramRequest = ramRequest;
        this.diskRequest = diskRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",");
        // Some lines might have trailing empty fields, split might drop them if not using negative limit.
        // But usually standard split is fine if we check length.
        // There are 13 fields.

        try {
            long timestamp = Long.parseLong(tokens[0]);
            String missingInfo = tokens[1];
            long jobId = Long.parseLong(tokens[2]);
            int taskIndex = Integer.parseInt(tokens[3]);
            String machineId = tokens[4];
            int eventType = Integer.parseInt(tokens[5]);
            String userName = tokens[6];
            int schedulingClass = tokens[7].isEmpty() ? -1 : Integer.parseInt(tokens[7]);
            int priority = tokens[8].isEmpty() ? -1 : Integer.parseInt(tokens[8]);

            float cpu = tokens.length > 9 && !tokens[9].isEmpty() ? Float.parseFloat(tokens[9]) : 0.0f;
            float ram = tokens.length > 10 && !tokens[10].isEmpty() ? Float.parseFloat(tokens[10]) : 0.0f;
            float disk = tokens.length > 11 && !tokens[11].isEmpty() ? Float.parseFloat(tokens[11]) : 0.0f;
            boolean constraint = tokens.length > 12 && "1".equals(tokens[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId, eventType, userName,
                    schedulingClass, priority, cpu, ram, disk, constraint);
        } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
             return null;
        }
    }
}

